Trên đường tròn tâm ${O}$ đường kính ${AF}$ lấy điểm ${H}$ sao cho $\widehat{AOH}=60^{\circ}$ . Xét tính đúng-sai của các khẳng định sau. 

\choiceTF
{  $\widehat{AHF}=60^{\circ}$ }
   { \True  $\widehat{AFH}= 30^{\circ}$ }
     { $ \widehat{HAF}=30^{\circ}$  }
    { \True $ \widehat{AHO}=60^{\circ}$  }
}{
\begin{tikzpicture}[scale=1, font=\footnotesize, line join=round, line cap=round, >=stealth]
                \def\r{2}   
                \path (0,0) coordinate (O)
                ($(O) + (180:\r)$) coordinate (A)
                ($(O) + (0:\r)$) coordinate (B)
                ($(O) + (110:\r)$) coordinate (C);
                \pgfresetboundingbox
                \draw (O) circle (\r)
                (A)--(B)--(C)--(A)--(O)--(B) (O)--(C);
