\choiceTF
{ \True $\widehat{BED}=90^{\circ}$ }
   { \True  $\widehat{BDE}= 40^{\circ}$ }
     { \True $ \widehat{EBD}=50^{\circ}$  }
    { $ \widehat{BEI}=40^{\circ}$  }
}{
